Lemma ConfigSvc_xpres : forall LB SP X m m' c S,
  ConfigSvc LB m c S -> xpres LB SP X m m' -> Forall (fun iv : Z * Z => c + NEWSZ_CFG <= fst iv \/ snd iv <= c) X ->
  ConfigSvc LB m' c S.
Proof.
  intros LB SP X m m' c S (p & j4 & j7 & IN & CH & E) XP FX. exists p, j4, j7.
  assert (XR : forall A n, c <= A -> A + n <= c + NEWSZ_CFG -> xclient_range LB SP X A n).
  { intros A n H1 H2. split; [right; right; exists (p, c, NEWSZ_CFG); split; [exact IN| cbn; lia]|].
    eapply Forall_impl; [| exact FX]. intros [lo hi] K; cbn in *; lia. }
  unfold NEWSZ_CFG in *. split; [exact IN|]. split; [| exact E]. xp_keep XP XR.
Qed.

Lemma StreamSvc_xpres : forall LB SP X m m' v S implb,
  StreamSvc LB m v S implb -> xpres LB SP X m m' -> Forall (fun iv : Z * Z => v + NEWSZ_SSVC <= fst iv \/ snd iv <= v) X ->
  StreamSvc LB m' v S implb.
Proof.
  intros LB SP X m m' v S implb (p & j7 & IN & CH & E) XP FX. exists p, j7.
  assert (XR : forall A n, v <= A -> A + n <= v + NEWSZ_SSVC -> xclient_range LB SP X A n).
  { intros A n H1 H2. split; [right; right; exists (p, v, NEWSZ_SSVC); split; [exact IN| cbn; lia]|].
    eapply Forall_impl; [| exact FX]. intros [lo hi] K; cbn in *; lia. }
  unfold NEWSZ_SSVC in *. split; [exact IN|]. split; [| exact E]. xp_keep XP XR.
Qed.
