(* [comment removed for export] *)
Lemma FlatBuf_xpres : forall LB SP X m m' a F ds,
  FlatBuf LB m a F ds -> xpres LB SP X m m' -> xclient_range LB SP X a SZ_FB ->
  (F <> FB_empty -> Forall (fun iv : Z * Z => fb_end F <= fst iv \/ snd iv <= fb_begin F) X) ->
  FlatBuf LB m' a F ds.
Proof.
  intros LB SP X m m' a F ds (C & OK & L & DATA) XP XA FD. split; [| split; [exact OK| split; [exact L|]]].
  - eapply xpres_rw_cells; [exact XP| exact C| exact XA].
  - intros NE. destruct (DATA NE) as (pre & junk & CD). exists pre, junk.
    destruct OK as [E|(p & IN & RB & CAP & O1 & O2)]; [contradiction|].
    pose proof (rw_cells_bound _ _ _ _ CD) as B. cbn [cells_size csize Nat.add] in B.
    destruct CD as [[WF BA] WR]. cbn in WF.
    eapply xpres_rw_cells; [exact XP| split; [split; [exact WF| exact BA] | exact WR] |].
    cbn [cells_size csize Nat.add]. unfold fb_cap, fb_size, zlength in *. split.
    + right; right. exists (p, fb_begin F, fb_end F - fb_begin F). split; [exact IN| cbn; lia].
    + eapply Forall_impl; [| exact (FD NE)]. intros [lo hi] K; cbn in *; lia.
Qed.

