Definition P_MI_RET1 : Z := 0x356bc.   (* [comment removed for export] *)
Definition P_MI_RET2 : Z := 0x356d4.   (* [comment removed for export] *)
Definition P_MI_RET3 : Z := 0x35700.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition mi_segA_post (sp gp tp t0 t1 t2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (R EX ioc regb lo : Z) (ra s0 s1 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' junk,
    ms' = MS (mkR (Z_to_bv 64 P_MI_RET1) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2
                  (Z_to_bv 64 R) (Z_to_bv 64 EX) (Z_to_bv 64 regb) (Z_to_bv 64 (bv_unsigned sp + -48)) (Z_to_bv 64 P_CREATE_SSVC) (Z_to_bv 64 ioc) a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_DO_USE_SERVICE) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -64)
    /\ rw_cells rsegs m' (bv_unsigned sp + -64) [CB 8 junk]
    /\ rw_cells rsegs m' (bv_unsigned sp + -56) [C8 (Z_to_bv 64 0)]
    /\ rw_cells rsegs m' (bv_unsigned sp + -48) [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 G_ID_SSVC)]
    /\ rw_cells rsegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra].

Lemma mi_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
