(* [comment removed for export] *)
(* [comment removed for export] *)

Definition MAKE_IMPL_STACK : Z := 64 + DUSC_STACK.
Definition MAKE_IMPL_LIVE : Z := NEWSZ_SSVC + SZ_SPCI_IMPL + SZ_SPCI_STATE + 8.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition sched_elt (ioc schedb cfgb : Z) : svce := mkSE schedb (sched_hdr ioc cfgb) TI_NAME_SCHED.

(* [comment removed for export] *)
Definition mi_LB (p1 : bptr) (v : Z) (p2 : bptr) (q : Z) (p3 : bptr) (stb : Z) (p4 : bptr) (va : Z) (LB : list block) : list block :=
  (p4, va, 8) :: (p3, stb, SZ_SPCI_STATE) :: (p2, q, SZ_SPCI_IMPL) :: (p1, v, NEWSZ_SSVC) :: LB.

Definition ssvc_hdr (ioc schedb : Z) : svch := mkSVC VP_SSVC 0 G_ID_SSVC ioc schedb P_DESTROY_ALLOC_SSVC.
Definition impl_after (va stb : Z) : implv := mkIMPL (mkSPC VP_SPCI_IMPL 1 2 1) 0 va [stb + O_SPC_STORAGE] 1.
Definition state_init : statev := mkST (mkSPC VP_SPCI_STATE 1 1 1) 0 FB_empty STREAM_OK 0 0.

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  Definition make_impl_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (R ioc allocb regb cfgb schedb slk sst ssh lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState)
                    (p1 : bptr) (v : Z) (p2 : bptr) (q : Z) (p3 : bptr) (stb : Z) (p4 : bptr) (va : Z),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ rblock_range v NEWSZ_SSVC /\ rblock_range q SZ_SPCI_IMPL /\ rblock_range stb SZ_SPCI_STATE /\ rblock_range va 8
      /\ hs_RHEAP H s' (mi_LB p1 v p2 q p3 stb p4 va LB) m'
      /\ rw_cells rsegs m' R [C8 (wz (stb + O_SPC_STORAGE)); C8 (wz stb)]
      /\ rw_cells rsegs m' ioc (IoCtxCells allocb regb schedb)
      /\ AllocImpl (mi_LB p1 v p2 q p3 stb p4 va LB) m' allocb
      /\ Registry (mi_LB p1 v p2 q p3 stb p4 va LB) m' regb ioc v 0
      /\ ConfigSvc (mi_LB p1 v p2 q p3 stb p4 va LB) m' cfgb (cfg_hdr ioc)
      /\ Scheduler (mi_LB p1 v p2 q p3 stb p4 va LB) m' schedb (mkSCH (sched_hdr ioc cfgb) slk sst ssh)
      /\ StreamSvc (mi_LB p1 v p2 q p3 stb p4 va LB) m' v (ssvc_hdr ioc schedb) q
      /\ ImplBlock (mi_LB p1 v p2 q p3 stb p4 va LB) m' q (impl_after va stb)
      /\ StateBlock (mi_LB p1 v p2 q p3 stb p4 va LB) m' stb ioc q state_init []
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) [(R, R + 16); (regb, regb + NEWSZ_REG)] m m'.

  Definition make_impl_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (R EX ioc allocb regb cfgb schedb slk sst ssh lo B : Z) (errv : word) (jr j16 : list byte),
      a0 = Z_to_bv 64 R -> a1 = Z_to_bv 64 EX -> a2 = Z_to_bv 64 0 ->
      (* [comment removed for export] *)
      rw_cells rsegs m R [CB 16 jr] -> bv_unsigned sp <= R -> R + 16 <= B -> R mod 8 = 0 ->
      ro_cells rsegs m EX (AnyExecCells EX ioc j16) -> bv_unsigned sp <= EX -> EX + 56 <= 2^64 -> EX mod 8 = 0 ->
      (R + 16 <= EX \/ EX + 56 <= R) ->
      (* [comment removed for export] *)
      rw_cells rsegs m ioc (IoCtxCells allocb regb schedb) -> bv_unsigned sp <= ioc -> ioc + 24 <= 2^64 -> ioc mod 8 = 0 ->
      (R + 16 <= ioc \/ ioc + 24 <= R) ->
      AllocImpl LB m allocb -> Registry LB m regb ioc schedb 0 -> ConfigSvc LB m cfgb (cfg_hdr ioc) ->
      Scheduler LB m schedb (mkSCH (sched_hdr ioc cfgb) slk sst ssh) -> XStatics m ->
      (* [comment removed for export] *)
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + MAKE_IMPL_LIVE <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 4 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B -> B < 2^64 ->
      (* [comment removed for export] *)
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - MAKE_IMPL_STACK ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned ra mod 2 = 0 ->
      hs_SR H (make_impl_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB R ioc allocb regb cfgb schedb slk sst ssh lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_SSVC_MAKE_IMPL) fc None m (seg_rom rsegs)) mo).

  Lemma make_impl_spec : make_impl_stmt.
  Proof.
    unfold make_impl_stmt. intros until j16.
    intros -> -> -> RR SPR RB R8 REX SPE EXH EX8 DRE IOC SPI IOH IO8 DRI AI REG CFG SCH XS HP KREL BUD BUDC AUX SPB BHI ST CEIL LO ERR MI TP RA.
    pose proof LO as LO'.
