    assert (FOq : forall a, rclient_addr LB (bv_unsigned sp + -64) a -> a + 1 <= q \/ q + 96 <= a).
    { intros a Ha. pose proof (fresh_outside_gen H HH _ [(p2, q, 96); (p1, v, 79)] LB _ (p2, q, 96) (bv_unsigned sp + -64) a HEAP2 ltac:(left; reflexivity) ltac:(clear - CEIL' LO SPR; lia) Ha) as X.
