    pose proof (INBv _ _ _ INR) as DRV. pose proof (INBq _ _ _ INR) as DRQ. pose proof (INBv _ _ _ INC) as DCV. pose proof (INBq _ _ _ INC) as DCQ.
    pose proof (INBv _ _ _ INS) as DSV. pose proof (INBq _ _ _ INS) as DSQ. pose proof (INBv _ _ _ INA) as DAV. pose proof (INBq _ _ _ INA) as DAQ.
    (* [comment removed for export] *)
    assert (XC2 : forall A n, bv_unsigned sp + -64 <= A -> xclient_range LB (bv_unsigned sp + -64) [(regb, regb + 79)] A n).
    { intros A n HA. split; [left; exact HA| constructor; [cbn; lia| constructor]]. }
    eapply (xpres_rw_cells _ _ _ m1 m2) in FR0; [| exact XP2| apply XC2; lia].
