      apply (proj1 (rw_cells_app _ _ _ [_; _] _)) in VCH. exact (proj1 (proj1 VCH)). }
    pose proof IMPL2 as (p2' & ij7 & INq & _ & IHDR & IOK & _).
    pose proof (make_shared_state_spec H HH) as MSS. unfold make_shared_state_stmt in MSS.
    eapply (hh_seq H HH).
    { eapply MSS with (R := R) (EX := EX) (SPP := v + 48) (FCP := bv_unsigned sp + -56) (implb := q) (ioc := ioc) (lo := lo) (B := B)
                      (LB := (p2, q, 96) :: (p1, v, 79) :: LB) (s := sB) (pi := p2) (ivp := VP_SPCI_IMPL) (iu := 1) (ii := 1);
        try reflexivity; rewrite ?unsigned_lit by lia.
      - f_equal. lia.
      - exact RR. - lia. - lia.
      - exact REX. - lia. - lia.
      - exact RSPP.
      - right; right. exists (p1, v, 79). split; [right; left; reflexivity| cbn; lia].
      - exact (proj1 FCP). - lia.
      - exact IHDR. - exact IOK. - left; reflexivity.
